message.content:
[
  {
    "ce_mental_state_attribution": "guess they'd freeze with fear",
    "ae_shared_affect": "feel that same freeze in my own chest",
    "pd_harm_distress": "my hands stopped shaking"
  },
  {
    "ce_mental_state_attribution": "five men start shouting in panic",
    "ae_shared_affect": "panic would get into me too"
  },
  {
    "pd_decision_conflict": "keep going back and forth",
    "ce_mental_state_attribution": "workers would be terrified once they notice",
    "ae_shared_affect": "terrified right along with them, the same fear"
  },
  {
    "ce_mental_state_attribution": "saw one of them turn and go pale",
    "ae_shared_affect": "my stomach would drop the exact way theirs did"
  },
  {
    "pda_responsibility": "whatever follows is on me",
    "ce_mental_state_attribution": "workers would likely be scrambling and frightened",
    "ae_shared_affect": "fright is contagious. I'd feel it as if it were mine"
  },
  {
    "pd_decision_conflict": "notice how much I want to push the question away",
    "ce_mental_state_attribution": "workers realizing, and their alarm",
    "ae_shared_affect": "alarm hitting me like a wave, the same alarm"
  },
  {
    "sys_consequence_reasoning": "since the siding is empty and the barrier stops",
    "pd_personal_consequence_anxiety": "palms are already sweating at the thought of getting it backwards",
    "ce_mental_state_attribution": "workers saw the train and started yelling",
    "ae_shared_affect": "their fear would pour straight into me. I'd share it"
  },
  {
    "pd_decision_conflict": "makes me want to act and also makes me want to hide",
    "ce_mental_state_attribution": "If they're scared",
    "ae_shared_affect": "I'm scared with them... shared fear"
  },
  {
    "ce_mental_state_attribution": "worker looking up in dread",
    "ae_shared_affect": "feeling that same dread"
  },
  {
    "ce_mental_state_attribution": "The workers, if they noticed, would be panicking",
    "ae_shared_affect": "feel that panic climbing in me as well"
  }
]
